 private static final class World extends NonRenderingChecks.MemoryWorld {World(boolean remote){super(remote);}@Override public net.minecraft.server.MinecraftServer getMinecraftServer(){return marker;}}
 private static final class Player extends EntityPlayer {int gui=-1;Player(World world){super(world,new com.mojang.authlib.GameProfile(new UUID(0,51),"StorageOracle"));setPosition(.5,80.5,.5);}@Override public boolean isSpectator(){return false;}@Override public boolean isCreative(){return capabilities.isCreativeMode;}@Override public void openGui(Object mod,int id,net.minecraft.world.World world,int x,int y,int z){gui=id;}}
 private static TileEntityProgrammableStorage install(World world){world.setBlockState(POS,block.getDefaultState(),18);return (TileEntityProgrammableStorage)world.getTileEntity(POS);}
 private static void load(TileEntityProgrammableStorage tile,World world,NBTTagCompound tag){tile.readFromNBT(tag);tile.setWorld(world);tile.setPos(POS);}
 private static JsonArray counts(TileEntityProgrammableStorage tile){JsonArray result=new JsonArray();for(int i=0;i<27;i++){ItemStack stack=tile.getStackInSlot(i);JsonObject row=new JsonObject();row.addProperty("count",stack.getCount());row.addProperty("item",stack.isEmpty()?"":stack.getItem().getRegistryName().toString());row.addProperty("damage",stack.getMetadata());result.add(row);}return result;}
 private static final String[] TAGS={"{}","{housingTexture:14}","{housingTexture:14,HousingTextureVersion:1}","{housingTexture:\"14\",SlabTileSides:1b}","{housingTexture:7,HousingTextureVersion:1,FaceTexturesEnabled:1b,FaceTextures:[I;-1,1,3,-1,-1,-1]}","{Items:[]}","{Items:[{Slot:0b,id:\"minecraft:iron_ingot\",Count:7b,Damage:0s},{Slot:26b,id:\"minecraft:ender_pearl\",Count:16b,Damage:0s}]}","{Items:[{Slot:0b,id:\"minecraft:diamond\",Count:2b},{Slot:0b,id:\"minecraft:iron_ingot\",Count:3b},{Slot:-1b,id:\"minecraft:diamond\",Count:4b},{Slot:27b,id:\"minecraft:diamond\",Count:5b}]}","{Items:[\"wrong-list-element\"]}","{Items:17}","{Items:[{Slot:0b,id:\"missing:opaque\",Count:1b,ForgeCaps:{foreign:{value:9}}}]}","{Items:[{Slot:0b,id:\"minecraft:stone\",Count:64b,Damage:1s,tag:{display:{Name:\"Legacy granite\"}}}]}","{housingTexture:99999,HousingTextureVersion:1,ForeignRoot:\"retained-source-observation\",RedstoneChannels:[I;17,19],ChannelLevel:15}"};
 private static JsonArray snapshots()throws Exception{JsonArray rows=new JsonArray();for(int seed=0;seed<3;seed++)for(int input=0;input<TAGS.length;input++){World world=new World(false);TileEntityProgrammableStorage tile=install(world);if(seed>0)tile.setInventorySlotContents(26,new ItemStack(net.minecraft.init.Items.DIAMOND,seed==1?7:64));NBTTagCompound raw=JsonToNBT.getTagFromJson(TAGS[input]);JsonObject row=new JsonObject();row.addProperty("seed",seed);row.addProperty("input",TAGS[input]);load(tile,world,raw);row.addProperty("mutatedInput",raw.toString());row.addProperty("saved",tile.writeToNBT(new NBTTagCompound()).toString());NBTTagCompound update=tile.getUpdateTag(),configured=block.createConfiguredDrop(tile).getSubCompound("BlockEntityTag");need(!update.hasKey("Items")&&!configured.hasKey("Items"),"public/pick excludes inventory");row.addProperty("public",update.toString());row.addProperty("configured",configured.toString());net.minecraft.util.NonNullList<ItemStack> drops=net.minecraft.util.NonNullList.create();block.getDrops(drops,world,POS,world.getBlockState(POS),0);need(drops.size()==1&&drops.get(0).getSubCompound("BlockEntityTag").equals(configured),"actual configured getDrops excludes inventory");ItemStack picked=block.getPickBlock(world.getBlockState(POS),new RayTraceResult(new Vec3d(.5,80.5,0),EnumFacing.NORTH,POS),world,POS,null);need(picked.getSubCompound("BlockEntityTag").equals(configured),"actual pick matches configured drop");row.add("slots",counts(tile));row.addProperty("comparator",block.getComparatorInputOverride(block.getDefaultState(),world,POS));need(tile.getSizeInventory()==27&&tile.getInventoryStackLimit()==64&&tile.getFieldCount()==0&&!tile.hasCustomName(),"released inventory constants");rows.add(row);}return rows;}
 private static JsonArray operations(){JsonArray rows=new JsonArray();Item[] types={net.minecraft.init.Items.IRON_INGOT,net.minecraft.init.Items.ENDER_PEARL,net.minecraft.init.Items.IRON_PICKAXE};for(int kind=0;kind<types.length;kind++)for(int slot:new int[]{0,13,26})for(int amount:new int[]{0,1,16,64,127})for(int take:new int[]{0,1,7,64}){World world=new World(false);TileEntityProgrammableStorage tile=install(world);ItemStack stack=new ItemStack(types[kind],amount);tile.setInventorySlotContents(slot,stack);int installed=tile.getStackInSlot(slot).getCount();ItemStack extracted=tile.decrStackSize(slot,take);JsonObject row=new JsonObject();row.addProperty("kind",kind);row.addProperty("slot",slot);row.addProperty("amount",amount);row.addProperty("take",take);row.addProperty("installed",installed);row.addProperty("extracted",extracted.getCount());row.addProperty("remaining",tile.getStackInSlot(slot).getCount());row.addProperty("comparator",block.getComparatorInputOverride(block.getDefaultState(),world,POS));row.addProperty("valid",tile.isItemValidForSlot(slot,stack));row.addProperty("removed",tile.removeStackFromSlot(slot).getCount());row.addProperty("emptyAfterRemove",tile.isEmpty());need(installed<=Math.min(64,types[kind].getItemStackLimit(stack)),"setter stack clamp");rows.add(row);}return rows;}
 private static JsonArray automation(){JsonArray rows=new JsonArray();for(EnumFacing side:EnumFacing.values())for(boolean simulate:new boolean[]{false,true})for(int initial:new int[]{0,60,64}){World world=new World(false);TileEntityProgrammableStorage tile=install(world);if(initial>0)tile.setInventorySlotContents(0,new ItemStack(net.minecraft.init.Items.IRON_INGOT,initial));IItemHandler handler=tile.getCapability(CapabilityItemHandler.ITEM_HANDLER_CAPABILITY,side);need(handler!=null&&handler.getSlots()==27,"all six sides expose same independent slots");int remaining=handler.insertItem(0,new ItemStack(net.minecraft.init.Items.IRON_INGOT,9),simulate).getCount();int inserted=tile.getStackInSlot(0).getCount();int extracted=handler.extractItem(0,5,simulate).getCount();JsonObject row=new JsonObject();row.addProperty("face",side.getIndex());row.addProperty("simulate",simulate);row.addProperty("initial",initial);row.addProperty("remainder",remaining);row.addProperty("afterInsert",inserted);row.addProperty("extracted",extracted);row.addProperty("final",tile.getStackInSlot(0).getCount());rows.add(row);}return rows;}
 private static JsonArray comparators(){JsonArray rows=new JsonArray();Item[] types={net.minecraft.init.Items.IRON_INGOT,net.minecraft.init.Items.ENDER_PEARL,net.minecraft.init.Items.IRON_PICKAXE};for(int kind=0;kind<3;kind++)for(int filled=0;filled<=27;filled++)for(int fraction=0;fraction<3;fraction++){World world=new World(false);TileEntityProgrammableStorage tile=install(world);int maximum=new ItemStack(types[kind]).getMaxStackSize(),count=fraction==0?1:fraction==1?Math.max(1,maximum/2):maximum;for(int slot=0;slot<filled;slot++)tile.setInventorySlotContents(slot,new ItemStack(types[kind],count));JsonObject row=new JsonObject();row.addProperty("kind",kind);row.addProperty("filled",filled);row.addProperty("count",count);row.addProperty("maximum",maximum);row.addProperty("signal",block.getComparatorInputOverride(block.getDefaultState(),world,POS));rows.add(row);}return rows;}
 private static JsonArray materials(){JsonArray rows=new JsonArray();for(int choice=0;choice<ScreenHousingTextures.BUILTIN_COUNT;choice++)if(ScreenHousingTextures.category(choice).equals("Storage")){JsonObject row=new JsonObject();row.addProperty("choice",choice);JsonArray faces=new JsonArray();for(EnumFacing face:EnumFacing.values())faces.add(ScreenHousingTextures.storageTexture(choice,face));row.add("faces",faces);rows.add(row);}need(rows.size()==14,"fourteen storage artwork sets");return rows;}
 private static JsonArray placement()throws Exception{JsonArray rows=new JsonArray();for(int input=0;input<8;input++)for(int yaw=0;yaw<4;yaw++)for(EnumFacing face:EnumFacing.values()){World world=new World(false);Player player=new Player(world);player.rotationYaw=yaw*90;NBTTagCompound raw=JsonToNBT.getTagFromJson(TAGS[input]);ItemStack stack=new ItemStack(item);stack.setTagInfo("BlockEntityTag",raw.copy());IBlockState state=block.getStateForPlacement(world,POS,face,.1F,.5F,.9F,0,player);need(item.placeBlockAt(stack,player,world,POS,face,.1F,.5F,.9F,state),"actual ItemBlock placement");TileEntityProgrammableStorage tile=(TileEntityProgrammableStorage)world.getTileEntity(POS);JsonObject row=new JsonObject();row.addProperty("input",TAGS[input]);row.addProperty("yaw",yaw);row.addProperty("face",face.getIndex());row.addProperty("meta",block.getMetaFromState(world.getBlockState(POS)));row.addProperty("saved",tile.writeToNBT(new NBTTagCompound()).toString());row.add("slots",counts(tile));row.addProperty("configured",block.createConfiguredDrop(tile).getSubCompound("BlockEntityTag").toString());rows.add(row);tile.onChunkUnload();tile.invalidate();}return rows;}
