 private static JsonObject ownership(){World world=new World(false);TileEntityProgrammableStorage source=install(world);BlockPos other=POS.east();world.setBlockState(other,block.getDefaultState(),18);TileEntityProgrammableStorage target=(TileEntityProgrammableStorage)world.getTileEntity(other);source.setInventorySlotContents(0,new ItemStack(net.minecraft.init.Items.IRON_INGOT,12));source.setFaceTextures(new FaceTextures(true,new int[]{-1,1,3,-1,-1,-1}));target.setInventorySlotContents(26,new ItemStack(net.minecraft.init.Items.DIAMOND,7));NBTTagCompound appearance=ProgrammableSettings.capture(world,POS);need(ProgrammableSettings.apply(world,other,appearance),"actual appearance apply");need(target.getStackInSlot(26).getCount()==7&&target.getFaceTextures().equals(source.getFaceTextures()),"copy appearance preserves target inventory");ItemStack configured=ProgrammableSettings.applyToItem(new ItemStack(item),appearance);need(!configured.getSubCompound("BlockEntityTag").hasKey("Items"),"copied item excludes inventory");source.setFaceTextures(new FaceTextures(false,new int[]{2,2,2,2,2,2}));need(ProgrammableSettings.apply(world,other,ProgrammableSettings.capture(world,POS)),"disabled appearance copy");need(!target.getFaceTextures().enabled&&target.getFaceTextures().choice(1)==1&&target.getFaceTextures().choice(2)==3&&target.getStackInSlot(26).getCount()==7,"disabled copy retains target stored faces and contents");Player player=new Player(world);ContainerChest menu=new ContainerChest(player.inventory,source,player);need(menu.inventorySlots.size()==63,"27+36 vanilla menu slots");need(menu.transferStackInSlot(player,0).getCount()==12&&source.isEmpty(),"actual quick-move extraction");int playerSlot=-1;for(int i=27;i<63;i++)if(menu.getSlot(i).getHasStack())playerSlot=i;need(playerSlot>=27&&menu.transferStackInSlot(player,playerSlot).getCount()==12&&source.getStackInSlot(0).getCount()==12,"actual quick-move insertion");block.breakBlock(world,POS,block.getDefaultState());int dropped=0;for(net.minecraft.entity.Entity entity:world.loadedEntityList)if(entity instanceof net.minecraft.entity.item.EntityItem&&((net.minecraft.entity.item.EntityItem)entity).getItem().getItem()==net.minecraft.init.Items.IRON_INGOT)dropped+=((net.minecraft.entity.item.EntityItem)entity).getItem().getCount();need(dropped==12&&source.isEmpty(),"actual break ejects contents once and empties inventory");JsonObject result=new JsonObject();result.addProperty("copy",appearance.toString());result.addProperty("target",target.writeToNBT(new NBTTagCompound()).toString());result.addProperty("item",configured.getSubCompound("BlockEntityTag").toString());result.addProperty("menuSlots",menu.inventorySlots.size());result.addProperty("breakItemCount",dropped);return result;}
 public static void main(String[] args)throws Exception{net.minecraft.init.Bootstrap.register();CapabilityItemHandler.register();java.lang.reflect.Field providerField=net.minecraftforge.common.capabilities.CapabilityManager.class.getDeclaredField("providers");providerField.setAccessible(true);CapabilityItemHandler.ITEM_HANDLER_CAPABILITY=(net.minecraftforge.common.capabilities.Capability<IItemHandler>)((Map<?,?>)providerField.get(net.minecraftforge.common.capabilities.CapabilityManager.INSTANCE)).get(IItemHandler.class.getName().intern());need(CapabilityItemHandler.ITEM_HANDLER_CAPABILITY!=null,"actual Forge capability initialized");com.vandorlabs.VandorLabs.proxy=new com.vandorlabs.CommonProxy();java.lang.reflect.Field unsafe=sun.misc.Unsafe.class.getDeclaredField("theUnsafe");unsafe.setAccessible(true);marker=(net.minecraft.server.MinecraftServer)((sun.misc.Unsafe)unsafe.get(null)).allocateInstance(net.minecraft.server.dedicated.DedicatedServer.class);net.minecraftforge.fml.common.registry.GameRegistry.registerTileEntity(TileEntityProgrammableStorage.class,new ResourceLocation("minecraft:storage_reference"));block=(BlockProgrammableStorage)ModBlocks.PROGRAMMABLE_STORAGE;net.minecraftforge.fml.common.registry.ForgeRegistries.BLOCKS.register(block);item=new ItemCatalogBlock(block);item.setRegistryName(block.getRegistryName());net.minecraftforge.fml.common.registry.ForgeRegistries.ITEMS.register(item);JsonObject root=new JsonObject();root.addProperty("schema",1);root.addProperty("inventorySize",27);root.addProperty("inventoryLimit",64);root.addProperty("name",new TileEntityProgrammableStorage().getName());root.addProperty("light",block.getLightValue(block.getDefaultState(),new World(false),POS));root.addProperty("factory",new TileEntityProgrammableStorage().writeToNBT(new NBTTagCompound()).toString());JsonArray metadata=new JsonArray();for(int meta=0;meta<32;meta++)metadata.add(block.getMetaFromState(block.getStateFromMeta(meta)));root.add("metadata",metadata);root.add("snapshots",snapshots());root.add("operations",operations());root.add("automation",automation());root.add("comparators",comparators());root.add("materials",materials());root.add("placement",placement());root.add("activation",activation());root.add("toolActivation",toolActivation());root.add("ownership",ownership());Path target=Paths.get("build/test-artifacts/storage-source-reference.json");Files.createDirectories(target.getParent());byte[] bytes=root.toString().getBytes("UTF-8");Files.write(target,bytes);StringBuilder hash=new StringBuilder();for(byte value:java.security.MessageDigest.getInstance("SHA-256").digest(bytes))hash.append(String.format("%02x",value&255));need(bytes.length<1024*1024&&hash.toString().equals("02a04c006aa4211dff586fa6fcaf8dae05f5d2eefbeb8cab3291feb265938fe5"),"frozen Source inventory/configuration corpus "+hash);System.out.println("Actual Storage Source PASS checks="+checks+" snapshots="+root.getAsJsonArray("snapshots").size()+" operations="+root.getAsJsonArray("operations").size()+" automation="+root.getAsJsonArray("automation").size()+" placement="+root.getAsJsonArray("placement").size()+" activation="+root.getAsJsonArray("activation").size()+" bytes="+bytes.length+" sha256="+hash);}
